def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c
    last_me = me[-1]
    last_opp = opp[-1]

    # --- Endgame exploitation ---
    if n >= 96:
        # Final rounds: defect unless opponent is a naive always-cooperator
        # and we want to preserve a bit of CC for the last rounds
        if opp_d == 0:
            return 'C'
        return 'D'

    # --- Opening phase ---
    if n == 1:
        return 'C'
    if n < 5:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # --- Strong signals ---
    if opp_d == 0:
        # Never defected; cooperate. Occasional late exploitation via endgame.
        return 'C'
    if opp_c == 0:
        return 'D'

    recent = opp[-6:]
    rec_c = sum(1 for x in recent if x == 'C')
    rec_d = len(recent) - rec_c

    # Detect near-pure defector
    if opp_d * 100 >= n * 82:
        # Almost always D; a rare probe is not worth it.
        return 'D'

    # Detect near-pure cooperator
    if opp_c * 100 >= n * 82:
        # Exploit but keep them cooperating: mostly D, occasional C.
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    # Detect tit-for-tat: opponent mimics our previous move
    if n >= 8:
        mimic = 0
        tot = 0
        for i in range(1, n):
            tot += 1
            if opp[i] == me[i - 1]:
                mimic += 1
        mimic_rate = mimic / tot if tot else 0.0
        if mimic_rate >= 0.75:
            # Mutual cooperation is optimal against TFT.
            # After last opp D, offer C to restore; but if opponent
            # oscillates, mirror.
            if last_opp == 'D':
                # forgive once if our last move was C (they retaliated for our C? unlikely)
                if last_me == 'C':
                    return 'D'
                return 'C'
            return 'C'

    # Detect long mutual cooperation window
    if rec_c >= 5 and opp_d <= 2:
        # Mostly cooperating: cooperate but probe occasionally late.
        if n >= 70 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # --- Generous tit-for-tat core with calibrated forgiveness ---
    if last_opp == 'C':
        # Opponent cooperated: reward with C. Exploit only if clearly safe.
        if opp_c * 100 >= n * 70 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # last_opp == 'D'
    # Count consecutive opponent defections at the tail
    cons_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            cons_d += 1
        else:
            break

    # If opponent is a frequent defector overall, defect
    if opp_d * 100 >= n * 55:
        # mixed defector: retaliate but rarely forgive to break spiral
        if cons_d >= 3:
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        if last_me == 'D':
            return 'D'
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # Moderate opponent defection rate -> tit-for-tat with forgiveness
    if cons_d == 1:
        # Single defection: retaliate once
        return 'D'
    if cons_d == 2:
        # Two in a row: punish but consider olive branch
        if rng.random() < 0.25:
            return 'C'
        return 'D'
    # Long streak: defect hard, occasionally test
    if rng.random() < 0.1:
        return 'C'
    return 'D'
